import type { CardProps } from "./card.types";
import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { DividerClasses } from "@components/divider";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Card";

// Generate child element class names for the component, should match available style slots
export const CardClasses = {
  root: "exp-textura_card",
  header: "exp-textura_card_header",
  content: "exp-textura_card_content",
  divider: "exp-textura_card_divider",
  spacingDefault: "exp-textura_card_spacing_default",
  spacingRoomy: "exp-textura_card_spacing_roomy",
  spacingTight: "exp-textura_card_spacing_tight",
};
// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  strong: {
    root: {
      backgroundColor: theme.card.strong.color.background,
      color: theme.card.strong.color.content,
      borderColor: theme.card.strong.color.border,
      boxShadow: "none",
    },
    dividerSm: {
      backgroundColor: theme.divider.default.color.strong,
    },
    dividerMd: {
      backgroundColor: theme.divider.default.color.strong,
    },
    dividerLg: {
      backgroundColor: theme.divider.default.color.strong,
    },
  },
  flat: {
    root: {
      backgroundColor: theme.card.flat.color.background,
      color: theme.card.flat.color.content,
      borderColor: theme.card.flat.color.border,
      boxShadow: "none",
    },
  },
});

const generateStyles = (props: CardProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<CardProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    border: `${theme.toRem(theme.card.border.width)} solid ${theme.card.elevated.color.border}`,
    borderRadius: theme.toRem(theme.card.border.radius),
    backgroundColor: theme.card.elevated.color.background,
    color: theme.card.elevated.color.content,
    boxShadow: theme.dropShadow.lg,
    overflow: "hidden",
    display: "flex",
    flexDirection: "column",

    [`&.${CardClasses.spacingDefault} > .${CardClasses.content}`]: {
      padding: theme.toRem(theme.spacing[16]),
      ...styleSlots?.spacingDefault,
    },

    [`&.${CardClasses.spacingRoomy} > .${CardClasses.content}`]: {
      padding: theme.toRem(theme.spacing[24]),
      ...styleSlots?.spacingRoomy,
    },

    [`&.${CardClasses.spacingTight} > .${CardClasses.content}`]: {
      padding: 0,
      ...styleSlots?.spacingTight,
    },

    [`.${CardClasses.header}`]: {
      all: "unset",
      padding: theme.toRem(theme.spacing[16]),
      ...theme.typography.subtitle.weak,
      ...styleSlots?.header,
    },

    [`.${CardClasses.content}`]: {
      flexGrow: 1,
      ...styleSlots?.content,
    },

    [`.${CardClasses.divider}`]: {
      [`&.${DividerClasses.sm}`]: {
        backgroundColor: theme.divider.default.color.default,
        ...styleSlots?.dividerSm,
      },
      [`&.${DividerClasses.md}`]: {
        backgroundColor: theme.divider.md.color.default,
        ...styleSlots?.dividerMd,
      },
      [`&.${DividerClasses.lg}`]: {
        backgroundColor: theme.divider.lg.color.default,
        ...styleSlots?.dividerLg,
      },
      ...styleSlots?.divider,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledCard = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CardProps>((props) => generateStyles(props));
